  static String of(BuildContext context, String key) {
    // Listening (watch) is needed while building so widgets refresh when the
    // language changes, but Provider forbids it inside event handlers
    // (onPressed, after an await, ...). Fall back to a non-listening read
    // there, so context.tr() is safe to call anywhere.
    String lang;
    try {
      lang = Provider.of<SettingsProvider>(context).languageCode;
    } catch (_) {
      lang = Provider.of<SettingsProvider>(context, listen: false).languageCode;
    }
    final e = _dict[key];
    // Pashto falls back to Dari (same script, closest language) before English
    if (e == null) return key;
    final String? fallbackFa = lang == 'ps' ? e['fa'] : null;
    return e[lang] ?? fallbackFa ?? e['en'] ?? key;
  }
}

extension TrContext on BuildContext {
  String tr(String key) => AppStrings.of(this, key);
}
